<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Oxygen,Ubuntu,sans-serif;background:#0a0a1a;color:#e0e0e0;line-height:1.6;overflow-x:hidden}
header{text-align:center;padding:2.5rem 1rem 1rem;background:linear-gradient(180deg,#12122a 0%,#0a0a1a 100%)}
