.about p{font-size:1.05rem;color:#9a9ab0;max-width:560px;margin:0 auto;line-height:1.8}
.collection{max-width:1100px;margin:0 auto;padding:2rem 1.5rem 4rem}
.collection h2{text-align:center;font-size:1.6rem;color:#d4af37;margin-bottom:2.5rem;font-weight:300;letter-spacing:0.08em;text-transform:uppercase}
