.edition{background:#12122a;border:1px solid #252540;border-radius:14px;padding:1.5rem 1.2rem;text-align:center;position:relative;transition:transform 0.3s ease,box-shadow 0.3s ease;overflow:hidden}
.edition:hover{transform:translateY(-5px);box-shadow:0 12px 40px rgba(212,175,55,0.08)}
.edition-canvas{width:180px;height:180px;margin:0 auto 1rem;display:block}
