<div class="season-badge">Spring</div>
</div>

</div>
</section>
</main>

<footer>
<p>WastedToken Mint &copy; 2024. All rights reserved.</p>
</footer>

<script>
(function(){
'use strict';

// === Coin Renderer ===
var CoinRenderer = {
  draw: function(ctx, cx, cy, radius, rotY, rotX, palette, time) {
    ctx.save();
    ctx.translate(cx, cy);
    var flipScale = Math.cos(rotX);
    var thickness = radius * 0.09;

    // Shadow
    ctx.save();
    ctx.translate(0, radius * 1.3);
    ctx.scale(1, 0.25);
    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.85, 0, Math.PI * 2);
    var sg = ctx.createRadialGradient(0, 0, 0, 0, 0, radius * 0.85);
    sg.addColorStop(0, 'rgba(0,0,0,0.35)');
    sg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = sg;
    ctx.fill();
    ctx.restore();

    // Edge
    this.drawEdge(ctx, radius, thickness, flipScale, palette, rotY, time);

    // Front face
    var frontAlpha = Math.max(0, Math.cos(rotY));
    if (frontAlpha > 0.01) {
      ctx.save();
      ctx.globalAlpha = frontAlpha;
      this.drawFace(ctx, radius, flipScale, palette.front, 'front', time);
      ctx.restore();
    }

    // Back face
    var backAlpha = Math.max(0, -Math.cos(rotY));
    if (backAlpha > 0.01) {
      ctx.save();
      ctx.globalAlpha = backAlpha;
      this.drawFace(ctx, radius, flipScale, palette.back, 'back', time);
      ctx.restore();
    }

    // Metallic overlay
    this.applyMetallicShading(ctx, radius, flipScale, rotY, time, palette);

    // Specular highlight
    this.drawSpecularHighlight(ctx, radius, flipScale, rotY, time, palette);

    ctx.restore();
  },

  drawEdge: function(ctx, radius, thickness, flipScale, palette, rotY, time) {
    ctx.save();
    ctx.scale(1, flipScale);
    var outerR = radius + thickness;
    var innerR = radius - thickness;

    // Edge body
    ctx.beginPath();
    ctx.arc(0, 0, outerR, 0, Math.PI * 2);
    ctx.arc(0, 0, innerR, 0, Math.PI * 2, true);
    var eg = ctx.createRadialGradient(0, 0, innerR, 0, 0, outerR);
    eg.addColorStop(0, palette.edgeInner);
    eg.addColorStop(0.4, palette.edgeMid);
    eg.addColorStop(1, palette.edgeOuter);
    ctx.fillStyle = eg;
    ctx.fill();

    // Reeded lines
    var reedCount = 60;
    var lightAngle = rotY + time * 0.3;
    for (var i = 0; i < reedCount; i++) {
      var angle = (i / reedCount) * Math.PI * 2;
      var x1 = Math.cos(angle) * (innerR + 0.5);
      var y1 = Math.sin(angle) * (innerR + 0.5);
      var x2 = Math.cos(angle) * (outerR - 0.5);
      var y2 = Math.sin(angle) * (outerR - 0.5);
      var brightness = 0.3 + 0.7 * Math.max(0, Math.cos(angle - lightAngle));
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.strokeStyle = 'rgba(255,255,255,' + (brightness * 0.15).toFixed(3) + ')';
      ctx.lineWidth = 0.8;
      ctx.stroke();
    }

    // Edge rim highlight
    ctx.beginPath();
    ctx.arc(0, 0, outerR, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.12)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.restore();
  },

  drawFace: function(ctx, radius, flipScale, palette, faceType, time) {
    ctx.save();
    ctx.scale(1, flipScale);

    // Clip to circle
    ctx.beginPath();
    ctx.arc(0, 0, radius - 2, 0, Math.PI * 2);
    ctx.clip();

    // Base face gradient
    var grad = ctx.createRadialGradient(-radius * 0.25, -radius * 0.25, 0, 0, 0, radius);
    grad.addColorStop(0, palette.light);
    grad.addColorStop(0.5, palette.mid);
    grad.addColorStop(1, palette.dark);
    ctx.fillStyle = grad;
    ctx.fillRect(-radius, -radius, radius * 2, radius * 2);

    // Face content
    if (faceType === 'front') {
      this.drawEmblem(ctx, radius, palette);
    } else {
      this.drawTokenCount(ctx, radius, palette);
    }

    ctx.restore();
  },

  drawEmblem: function(ctx, radius, palette) {
    var r = radius * 0.55;

    // Outer decorative ring
    ctx.beginPath();
    ctx.arc(0, 0, r + 4, 0, Math.PI * 2);
    ctx.strokeStyle = palette.emblem;
    ctx.lineWidth = 2;
    ctx.stroke();

    // Inner circle
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    var ig = ctx.createRadialGradient(-r * 0.2, -r * 0.2, 0, 0, 0, r);
    ig.addColorStop(0, palette.emblemBgLight);
    ig.addColorStop(1, palette.emblemBg);
    ctx.fillStyle = ig;
    ctx.fill();
    ctx.strokeStyle = palette.emblem;
    ctx.lineWidth = 2.5;
    ctx.stroke();

    // Inner ring
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.72, 0, Math.PI * 2);
    ctx.strokeStyle = palette.emblem;
    ctx.lineWidth = 1;
    ctx.stroke();

    // WT text
    ctx.fillStyle = palette.emblemText;
    ctx.font = 'bold ' + (r * 0.55) + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('WT', 0, 0);

    // WASTEDTOKEN around
    ctx.font = (r * 0.22) + 'px sans-serif';
    ctx.fillStyle = palette.emblem;
    ctx.fillText('WASTEDTOKEN', 0, r * 0.82);

    // Small diamond accents
    var dr = r * 0.9;
    ctx.fillStyle = palette.emblem;
    for (var i = 0; i < 4; i++) {
      var a = (i / 4) * Math.PI * 2 + Math.PI / 4;
      ctx.beginPath();
      ctx.arc(Math.cos(a) * dr, Math.sin(a) * dr, 3, 0, Math.PI * 2);
      ctx.fill();
    }
  },

  drawTokenCount: function(ctx, radius, palette) {
    // Token count text
    ctx.fillStyle = palette.tokenText;
    ctx.font = 'bold ' + (radius * 0.28) + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('10,000', 0, -radius * 0.08);

    ctx.font = (radius * 0.14) + 'px sans-serif';
    ctx.fillStyle = palette.tokenSub;
    ctx.fillText('TOKENS', 0, radius * 0.18);

    // Decorative border
    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.7, 0, Math.PI * 2);
    ctx.strokeStyle = palette.tokenBorder;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Inner ring
    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.5, 0, Math.PI * 2);
    ctx.strokeStyle = palette.tokenBorder;
    ctx.lineWidth = 0.8;
    ctx.stroke();

    // Small text
    ctx.font = (radius * 0.1) + 'px sans-serif';
    ctx.fillStyle = palette.tokenSub;
    ctx.fillText('MINTED', 0, radius * 0.35);
  },

  applyMetallicShading: function(ctx, radius, flipScale, rotY, time, palette) {
    ctx.save();
    ctx.scale(1, flipScale);

    // Main metallic gradient - offset based on rotation
    var lightOffset = Math.cos(rotY) * radius * 0.4;
    var grad = ctx.createRadialGradient(lightOffset, -lightOffset * 0.5, 0, 0, 0, radius);
    grad.addColorStop(0, 'rgba(255,255,255,0.08)');
    grad.addColorStop(0.3, 'rgba(255,255,255,0)');
    grad.addColorStop(0.6, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.35)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(0, 0, radius - 1, 0, Math.PI * 2);
    ctx.fill();

    // Rim light on one side
    var rimAngle = rotY + Math.PI * 0.5;
    var rimX = Math.cos(rimAngle) * radius * 0.95;
    var rimY = Math.sin(rimAngle) * radius * 0.95;
    var rimGrad = ctx.createRadialGradient(rimX, rimY, 0, rimX, rimY, radius * 0.5);
    rimGrad.addColorStop(0, 'rgba(255,255,255,0.15)');
    rimGrad.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = rimGrad;
    ctx.beginPath();
    ctx.arc(0, 0, radius - 1, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  },

  drawSpecularHighlight: function(ctx, radius, flipScale, rotY, time, palette) {
    ctx.save();
    ctx.scale(1, flipScale);

    // Specular highlight position moves with rotation
    var highlightAngle = rotY + time * 0.8;
    var hx = Math.cos(highlightAngle) * radius * 0.35;
    var hy = Math.sin(highlightAngle) * radius * 0.35 - radius * 0.1;

    // Main specular spot
    var sg = ctx.createRadialGradient(hx, hy, 0, hx, hy, radius * 0.35);
    sg.addColorStop(0, 'rgba(255,255,255,0.55)');
    sg.addColorStop(0.3, 'rgba(255,255,255,0.15)');
    sg.addColorStop(0.7, 'rgba(255,255,255,0.02)');
    sg.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = sg;
    ctx.beginPath();
    ctx.arc(0, 0, radius - 1, 0, Math.PI * 2);
    ctx.fill();

    // Secondary smaller highlight
    var hx2 = Math.cos(highlightAngle + Math.PI) * radius * 0.15;
    var hy2 = Math.sin(highlightAngle + Math.PI) * radius * 0.15;
    var sg2 = ctx.createRadialGradient(hx2, hy2, 0, hx2, hy2, radius * 0.15);
    sg2.addColorStop(0, 'rgba(255,255,255,0.25)');
    sg2.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = sg2;
    ctx.beginPath();
    ctx.arc(0, 0, radius - 1, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }
};

// === Palettes ===
var bronzePalette = {
  edgeInner: '#5c2e0a', edgeMid: '#8b4513', edgeOuter: '#3a1a05',
  reed: '#2a1000',
  front: { light: '#e8c07a', mid: '#c89040', dark: '#8b5a20' },
  back: { light: '#d4a050', mid: '#a07030', dark: '#6b4020' },
  emblem: '#ffd700', emblemBg: '#2a1a0a', emblemBgLight: '#4a3010', emblemText: '#fff8e0',
  tokenText: '#ffd700', tokenSub: '#c89040', tokenBorder: '#8b5a20'
};

var silverPalette = {
  edgeInner: '#505050', edgeMid: '#808080', edgeOuter: '#3a3a3a',
  reed: '#2a2a2a',
  front: { light: '#f0f0f0', mid: '#c8c8c8', dark: '#888888' },
  back: { light: '#e0e0e0', mid: '#b0b0b0', dark: '#707070' },
  emblem: '#e8e8e8', emblemBg: '#1a1a2a', emblemBgLight: '#3a3a4a', emblemText: '#ffffff',
  tokenText: '#e0e0e0', tokenSub: '#a0a0a0', tokenBorder: '#808080'
};

var goldPalette = {
  edgeInner: '#8b6914', edgeMid: '#b8860b', edgeOuter: '#5a4008',
  reed: '#3a2800',
  front: { light: '#ffe680', mid: '#ffd700', dark: '#b8860b' },
  back: { light: '#ffe060', mid: '#daa520', dark: '#8b6914' },
  emblem: '#ffffff', emblemBg: '#2a2000', emblemBgLight: '#4a3800', emblemText: '#fff8e0',
  tokenText: '#ffd700', tokenSub: '#daa520', tokenBorder: '#b8860b'
};

var blackPalette = {
  edgeInner: '#1a1a1a', edgeMid: '#3a3a3a', edgeOuter: '#0a0a0a',
  reed: '#050505',
  front: { light: '#4a4a4a', mid: '#2a2a2a', dark: '#111111' },
  back: { light: '#3a3a3a', mid: '#222222', dark: '#0a0a0a' },
  emblem: '#d4af37', emblemBg: '#1a1a1a', emblemBgLight: '#2a2a2a', emblemText: '#d4af37',
  tokenText: '#d4af37', tokenSub: '#8a7020', tokenBorder: '#5a4a10'
};

// === Hero Coin ===
var heroCanvas = document.getElementById('coin-hero');
var heroCtx = heroCanvas.getContext('2d');
var animationId = null;
var isPaused = false;
var currentTime = 0;

function renderHeroCoin(t) {
  var ctx = heroCtx;
  var w = heroCanvas.width;
  var h = heroCanvas.height;
  var cx = w / 2;
  var cy = h / 2;
  var radius = Math.min(w, h) * 0.32;

  ctx.clearRect(0, 0, w, h);

  // Simple backdrop
  ctx.fillStyle = '#0a0a1a';
  ctx.fillRect(0, 0, w, h);

  // Subtle radial glow behind coin
  var glow = ctx.createRadialGradient(cx, cy, radius * 0.5, cx, cy, radius * 2);
  glow.addColorStop(0, 'rgba(212,175,55,0.06)');
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, w, h);

  // Calculate rotation angles
  var rotY = t * Math.PI * 2;
  var rotX = Math.sin(t * Math.PI * 2) * Math.PI / 3;

  CoinRenderer.draw(ctx, cx, cy, radius, rotY, rotX, bronzePalette, t);
}

// === Animation Loop ===
function animate() {
  if (isPaused) return;
  currentTime += 0.004;
  if (currentTime >= 1) currentTime -= 1;
  renderHeroCoin(currentTime);
  animationId = requestAnimationFrame(animate);
}

// === Edition Coins ===
function renderEditionCoin(canvas, palette) {
  var ctx = canvas.getContext('2d');
  var w = canvas.width;
  var h = canvas.height;
  var cx = w / 2;
  var cy = h / 2;
  var radius = Math.min(w, h) * 0.35;

  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = '#0a0a1a';
  ctx.fillRect(0, 0, w, h);

  // Subtle glow
  var glow = ctx.createRadialGradient(cx, cy, radius * 0.3, cx, cy, radius * 1.5);
  glow.addColorStop(0, 'rgba(212,175,55,0.04)');
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, w, h);

  CoinRenderer.draw(ctx, cx, cy, radius, 0.3, 0.15, palette, 0.5);
}

function initEditionCanvases() {
  var editions = [
    { sel: '[data-edition="bronze"]', pal: bronzePalette },
    { sel: '[data-edition="silver"]', pal: silverPalette },
    { sel: '[data-edition="gold"]', pal: goldPalette },
    { sel: '[data-edition="black"]', pal: blackPalette }
  ];
  editions.forEach(function(e) {
    var canvas = document.querySelector(e.sel + ' .edition-canvas');
    if (canvas) renderEditionCoin(canvas, e.pal);
  });
}

// === API ===
window.demo = {
  canvas: heroCanvas,
  setTime: function(t) {
    renderHeroCoin(t);
  },
  pause: function() {
    isPaused = true;
    if (animationId) {
      cancelAnimationFrame(animationId);
      animationId = null;
    }
  }
};

// === Init ===
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', function() {
    initEditionCanvases();
    animate();
  });
} else {
  initEditionCanvases();
  animate();
}

})();
</script>
</body>
</html>
```
